function exportCsv(){const arr=reportList();const headers=['Booking Ref','External Ref','Date','Time','Passenger','Phone','Source','Pickup','Via','Drop-off','Driver','Vehicle','Dispatch','Total Fare','Driver Fare','Driver Penalty','Driver Penalty Reason','Company Penalty / Chargeback','Company Penalty Reason','Net Company Margin','Complaint','Complaint Resolved','Driver Payment','Staff Comment','Driver Notes','Office Comments'];const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[headers.join(','),...arr.map(b=>[b.id,b.externalRef,b.date,b.time,b.passenger,b.phone,accountName(b.sourceId),b.pickup,(b.vias||[]).join(' | '),b.dropoff,driverName(b.driverId),vehicleText(b.vehicleId),b.dispatch,b.fare,b.driverFare||0,b.penaltyAmount||0,b.penaltyReason||'',b.companyPenaltyAmount||0,b.companyPenaltyReason||'',bookingNetMargin(b),b.complaint?'Yes':'No',b.complaintResolved?'Yes':'No',b.driverPaid?'Paid':'Pending',b.dashboardComment,b.driverNotes,b.officeComments].map(esc).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`private-hire-report-${$('reportFrom').value||'all'}-to-${$('reportTo').value||'all'}.csv`;a.click();URL.revokeObjectURL(a.href)}
$('downloadCsv').onclick=exportCsv;

function reportMeta(){
  const arr=reportList();
  const total=arr.reduce((s,b)=>s+Number(b.fare||0),0),driver=arr.reduce((s,b)=>s+Number(b.driverFare||0),0),driverPenalty=arr.reduce((s,b)=>s+Number(b.penaltyAmount||0),0),companyPenalty=arr.reduce((s,b)=>s+Number(b.companyPenaltyAmount||0),0),margin=total-driver+driverPenalty-companyPenalty;
  const companyId=$('reportCompany').value;
  return {arr,total,driver,driverPenalty,companyPenalty,margin,from:$('reportFrom').value||'',to:$('reportTo').value||'',company:companyId?accountName(companyId):'All Companies / Accounts'};
}
function reportPrintHtml(){
  const r=reportMeta();
  const rows=r.arr.map(b=>{const cls=b.complaint?(b.complaintResolved?'resolved':'complaint'):'';return `<tr class="${cls}"><td>${escapeHtml(b.id)}</td><td>${b.date}<br><small>${b.time}</small></td><td>${escapeHtml(b.passenger)}</td><td>${escapeHtml(b.pickup)}</td><td>${escapeHtml(b.dropoff)}</td><td>${escapeHtml(accountName(b.sourceId))}</td><td>${escapeHtml(b.dispatch)}</td><td>${money(b.fare)}</td><td>${money(b.driverFare||0)}</td><td>${Number(b.penaltyAmount||0)?'+'+money(b.penaltyAmount):'-'}<br><small>${escapeHtml(b.penaltyReason||'')}</small></td><td>${Number(b.companyPenaltyAmount||0)?'-'+money(b.companyPenaltyAmount):'-'}<br><small>${escapeHtml(b.companyPenaltyReason||'')}</small></td><td><strong>${money(bookingNetMargin(b))}</strong></td><td>${b.complaint?(b.complaintResolved?'Resolved':'Complaint - Open'):'-'}</td><td>${b.driverPaid?'Paid':'Pending'}</td></tr>`}).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><title>Private Hire Booking Report</title><style>@page{size:A4 landscape;margin:8mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17233a;margin:0;font-size:8px}.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #1767ed;padding-bottom:7px;margin-bottom:8px}.brand{font-size:17px;font-weight:800;color:#071b33}.brand small{display:block;font-size:7px;font-weight:500;color:#65758a;margin-top:2px}.meta{text-align:right;font-size:7px;line-height:1.5}.title{font-size:13px;font-weight:800;margin:0 0 3px}.summary{display:grid;grid-template-columns:repeat(6,1fr);gap:5px;margin:7px 0 9px}.kpi{border:1px solid #dbe3ef;border-radius:5px;padding:6px}.kpi span{display:block;color:#69798f;font-size:6px}.kpi strong{font-size:10px;display:block;margin-top:2px}table{width:100%;border-collapse:collapse;table-layout:fixed}th{background:#0b2849;color:#fff;padding:5px 3px;font-size:6px;text-align:left}td{padding:4px 3px;border-bottom:1px solid #e2e7ef;vertical-align:top;overflow-wrap:anywhere}small{font-size:6px;color:#69798f}.complaint td{background:#ffe3e6;color:#7c2430}.complaint small{color:#8a3a44}.resolved td{background:#e3f7e9;color:#174f30}.resolved small{color:#347150}.foot{margin-top:7px;font-size:6px;color:#718096;text-align:right}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="head"><div><div class="brand">Private Hire Booking Control Dashboard<small>Professional Booking & Financial Report</small></div><h1 class="title">Booking Report</h1><div>${escapeHtml(r.from)} to ${escapeHtml(r.to)} &nbsp; | &nbsp; ${escapeHtml(r.company)}</div></div><div class="meta">Generated: ${new Date().toLocaleString()}<br>Total records: ${r.arr.length}</div></div><div class="summary"><div class="kpi"><span>BOOKINGS</span><strong>${r.arr.length}</strong></div><div class="kpi"><span>TOTAL FARE</span><strong>${money(r.total)}</strong></div><div class="kpi"><span>DRIVER FARE</span><strong>${money(r.driver)}</strong></div><div class="kpi"><span>DRIVER PENALTIES</span><strong>+${money(r.driverPenalty)}</strong></div><div class="kpi"><span>COMPANY PENALTIES</span><strong>-${money(r.companyPenalty)}</strong></div><div class="kpi"><span>NET MARGIN</span><strong>${money(r.margin)}</strong></div></div><table><thead><tr><th>Ref</th><th>Date</th><th>Passenger</th><th>From</th><th>To</th><th>Company</th><th>Status</th><th>Total</th><th>Driver</th><th>Drv Pen.</th><th>Co. Pen.</th><th>Net</th><th>Complaint</th><th>Pay</th></tr></thead><tbody>${rows||'<tr><td colspan="14">No report data.</td></tr>'}</tbody></table><div class="foot">Net Margin = Total Fare − Driver Fare + Driver Penalties − Company Penalties / Chargebacks</div></body></html>`;
}
function printProfessionalReport(){
  const w=window.open('','_blank','width=1200,height=850');
  if(!w){alert('Please allow pop-ups to print the report.');return;}
  w.document.open();w.document.write(reportPrintHtml());w.document.close();w.focus();setTimeout(()=>w.print(),250);
}
function downloadReportPdf(){
  const r=reportMeta();
  if(!window.jspdf||!window.jspdf.jsPDF){alert('PDF library is still loading. Please try again in a moment.');return;}
  const {jsPDF}=window.jspdf;const doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});
  doc.setTextColor(7,27,51);doc.setFontSize(16);doc.setFont(undefined,'bold');doc.text('Private Hire Booking Control Dashboard',10,12);
  doc.setFontSize(10);doc.text('Booking & Financial Report',10,18);doc.setFont(undefined,'normal');doc.setFontSize(7);doc.setTextColor(90,105,125);doc.text(`${r.from} to ${r.to} | ${r.company}`,10,23);
  doc.setTextColor(16,33,59);doc.setFontSize(7.5);doc.text(`Bookings: ${r.arr.length}`,10,29);doc.text(`Total: ${money(r.total)}`,42,29);doc.text(`Driver: ${money(r.driver)}`,78,29);doc.text(`Driver Penalties: +${money(r.driverPenalty)}`,116,29);doc.text(`Company Penalties: -${money(r.companyPenalty)}`,167,29);doc.text(`Net Margin: ${money(r.margin)}`,222,29);
  const body=r.arr.map(b=>[b.id,`${b.date}\n${b.time}`,b.passenger,b.pickup,b.dropoff,accountName(b.sourceId),b.dispatch,money(b.fare),money(b.driverFare||0),Number(b.penaltyAmount||0)?`+${money(b.penaltyAmount)}`:'-',Number(b.companyPenaltyAmount||0)?`-${money(b.companyPenaltyAmount)}`:'-',money(bookingNetMargin(b)),b.complaint?(b.complaintResolved?'Resolved':'Open'):'-',b.driverPaid?'Paid':'Pending']);
  doc.autoTable({startY:34,head:[['Ref','Date','Passenger','From','To','Company','Status','Total','Driver','Drv Pen.','Co. Pen.','Net','Complaint','Pay']],body,theme:'grid',styles:{fontSize:5.3,cellPadding:1.25,valign:'top',overflow:'linebreak'},headStyles:{fillColor:[11,40,73],textColor:255,fontStyle:'bold'},columnStyles:{0:{cellWidth:14},1:{cellWidth:15},2:{cellWidth:21},3:{cellWidth:29},4:{cellWidth:29},5:{cellWidth:20},6:{cellWidth:18},7:{cellWidth:14},8:{cellWidth:14},9:{cellWidth:14},10:{cellWidth:14},11:{cellWidth:14},12:{cellWidth:18},13:{cellWidth:14}},didParseCell:data=>{if(data.section==='body'){const b=r.arr[data.row.index];if(b&&b.complaint){if(b.complaintResolved){data.cell.styles.fillColor=[227,247,233];data.cell.styles.textColor=[23,79,48]}else{data.cell.styles.fillColor=[255,227,230];data.cell.styles.textColor=[124,36,48]}}}},didDrawPage:()=>{doc.setFontSize(6);doc.setTextColor(110);doc.text(`Page ${doc.internal.getNumberOfPages()}`,286,202,{align:'right'})}});
  doc.save(`private-hire-report-${r.from||'all'}-to-${r.to||'all'}.pdf`);
}
$('downloadPdf').onclick=downloadReportPdf;$('printReport').onclick=printProfessionalReport;


